"""Pure translation from settings to the Lua file Hyprland loads last (~/.config/hypr/ui.lua)."""
from hyde_settings import model

HEADER = (
    "-- GENERATED BY hyde-settings — do not edit; change it in the app.\n"
    "-- Source: ~/.config/hyde-settings/settings.json\n"
)
CAPTURE_SUBMAP = "hs_capture"
RULE_PREFIX = "hs-"

_ESCAPES = {"\\": "\\\\", '"': '\\"', "\n": "\\n", "\r": "\\r", "\t": "\\t"}

DISPATCH_LUA = {
    "close": "hl.dsp.window.close()",
    "kill": "hl.dsp.window.kill()",
    "maximize": 'hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" })',
    "fullscreen": 'hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" })',
    "float": 'hl.dsp.window.float({ action = "toggle" })',
    "cycle_next": "hl.dsp.window.cycle_next()",
    "workspace": "hl.dsp.focus({{ workspace = {n} }})",
    "move_to_workspace": "hl.dsp.window.move({{ workspace = {n} }})",
}


def lua_str(text):
    out = []
    for ch in text:
        if ch in _ESCAPES:
            out.append(_ESCAPES[ch])
        elif ord(ch) < 32 or ord(ch) == 127:
            out.append(f"\\{ord(ch):03d}")
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def lua_num(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"not a number: {value!r}")
    return str(value) if isinstance(value, int) else repr(float(value))


def _prune(d):
    out = {}
    for key, value in d.items():
        if isinstance(value, dict):
            value = _prune(value)
        if value is None or value == {}:
            continue
        out[key] = value
    return out


def _lua_value(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, str):
        return lua_str(value)
    if isinstance(value, (int, float)):
        return lua_num(value)
    if isinstance(value, dict):
        return lua_table(value)
    raise TypeError(f"cannot emit {value!r}")


def lua_table(d):
    """Render a dict as a Lua table. Keys must be identifiers; None values and empty tables are skipped."""
    items = [f"{key} = {_lua_value(value)}" for key, value in _prune(d).items()]
    return "{ " + ", ".join(items) + " }" if items else "{}"


def action_lua(action):
    if action["type"] == "exec":
        return f"hl.dsp.exec_cmd({lua_str(action['command'])})"
    name = action["name"]
    if model.DISPATCHERS[name]:
        return DISPATCH_LUA[name].format(n=int(action["args"]["n"]))
    return DISPATCH_LUA[name]


def _capture_section():
    return (
        f"hl.define_submap({lua_str(CAPTURE_SUBMAP)}, function()\n"
        '\thl.bind("Escape", hl.dsp.submap("reset"), { description = "[hyde-settings] leave key capture" })\n'
        "end)\n"
    )


def _monitor_section(monitors):
    return "".join(
        "hl.monitor("
        + lua_table({"output": m["output"], "mode": m["mode"], "position": m["position"], "scale": m["scale"]})
        + ")\n"
        for m in monitors
    )


def _config_section(settings):
    inp, app = settings["input"], settings["appearance"]
    blur = app.get("blur") or {}
    table = _prune({
        "input": {
            "kb_layout": inp.get("kb_layout"),
            "kb_variant": inp.get("kb_variant"),
            "sensitivity": inp.get("sensitivity"),
            "numlock_by_default": inp.get("numlock_by_default"),
            "touchpad": {"natural_scroll": inp.get("natural_scroll")},
        },
        "general": {
            "gaps_in": app.get("gaps_in"),
            "gaps_out": app.get("gaps_out"),
            "border_size": app.get("border_size"),
        },
        "decoration": {
            "active_opacity": app.get("active_opacity"),
            "inactive_opacity": app.get("inactive_opacity"),
            "rounding": app.get("rounding"),
            "blur": {"enabled": blur.get("enabled"), "size": blur.get("size"), "passes": blur.get("passes")},
        },
    })
    return f"hl.config({lua_table(table)})\n" if table else ""


def _bind_lines(combo, action_expr, description):
    key = lua_str(model.normalize_combo(combo))
    return f"hl.unbind({key})\nhl.bind({key}, {action_expr}, {lua_table({'description': description})})\n"


def _apps_section(apps):
    out = ""
    for role in model.ROLES:
        entry = apps.get(role) or {}
        if entry.get("command"):
            action = f"hl.dsp.exec_cmd({lua_str(entry['command'])})"
            out += _bind_lines(entry["key"], action, model.ROLE_DESCRIPTIONS[role])
    return out


def _binds_section(binds):
    out = ""
    for bind in binds:
        if bind["action"]["type"] == "unbind":
            out += f"hl.unbind({lua_str(model.normalize_combo(bind['key']))})\n"
        else:
            out += _bind_lines(bind["key"], action_lua(bind["action"]), bind.get("description"))
    return out


def _window_rules_section(rules):
    out = ""
    for rule in rules:
        match = {key: rule["match"][key] for key in ("class", "title", "initial_title") if rule["match"].get(key)}
        idle = rule.get("idle_inhibit")
        if idle == "fullscreen":
            match["fullscreen"] = True
        opacity = rule.get("opacity")
        table = {
            "name": RULE_PREFIX + rule["name"],
            "match": match,
            "opacity": " ".join(f"{lua_num(x)} override" for x in opacity) if opacity else None,
            "float": rule.get("float"),
            "idle_inhibit": "always" if idle else None,
        }
        out += f"hl.window_rule({lua_table(table)})\n"
    return out


def _layer_rules_section(rules):
    out = ""
    for rule in rules:
        table = {
            "name": RULE_PREFIX + rule["name"],
            "match": {"namespace": rule["match"]["namespace"]},
            "blur": rule.get("blur"),
            "ignore_alpha": rule.get("ignore_alpha"),
        }
        out += f"hl.layer_rule({lua_table(table)})\n"
    return out


def generate(settings):
    sections = [
        HEADER,
        _capture_section(),
        _monitor_section(settings["monitors"]),
        _config_section(settings),
        _apps_section(settings["apps"]),
        _binds_section(settings["binds"]),
        _window_rules_section(settings["window_rules"]),
        _layer_rules_section(settings["layer_rules"]),
    ]
    return "\n".join(section for section in sections if section)
